 * Petshop DP Kortelės Ženkliukas v4 (CSS overlay)
 * ×N VNT. badge + EKONOMIŠKA PAKUOTĖ juosta — CSS overlay ant .box-image (image wrapper).
 * Injekcija per woocommerce_product_get_image filtra (loop kontekste) -> badge lieka box-image viduje.
 */

if (!function_exists('petshop_dp_ov_size')) {
function petshop_dp_ov_size($name) {
    if (preg_match('/(\d+(?:[.,]\d+)?)\s*(kg|g|ml|l)\b/iu', $name, $m)) {
        return str_replace('.', ',', $m[1]) . ' ' . strtolower($m[2]);
    }
    return '';
}
}

// Loop kontekstas
add_action('woocommerce_before_shop_loop_item', function(){ $GLOBALS['psc_dp_loop'] = true; }, 1);
add_action('woocommerce_after_shop_loop_item', function(){ $GLOBALS['psc_dp_loop'] = false; }, 99);

// Badge HTML generatorius
if (!function_exists('petshop_dp_badge_html')) {
function petshop_dp_badge_html($pid) {
    $qty = get_post_meta($pid, '_dp_pack_qty', true);
    if (!$qty) return '';
    $qty = intval($qty);
    $html = '<div class="psc-qty-badge"><span class="psc-qty-num">&times;' . $qty . '</span><span class="psc-qty-vnt">VNT.</span></div>';
    $base_id = get_post_meta($pid, '_dp_base_product_id', true);
    $size = '';
    if ($base_id) { $b = wc_get_product($base_id); if ($b) $size = petshop_dp_ov_size($b->get_name()); }
    if ($size !== '') {
        $band = 'EKONOMIŠKA PAKUOTĖ &middot; ' . $qty . ' &times; ' . esc_html($size);
    } else {
        $band = 'EKONOMIŠKA PAKUOTĖ &middot; ' . $qty . ' VNT.';
    }
    $html .= '<div class="psc-eco-band">' . $band . '</div>';
    return $html;
}
}

// Injekcija i loop nuotrauka (box-image viduje)
add_filter('woocommerce_product_get_image', function($html, $product){
    if (empty($GLOBALS['psc_dp_loop'])) return $html;
    if (!$product) return $html;
    $badge = petshop_dp_badge_html($product->get_id());
    return $badge ? ($html . $badge) : $html;
}, 20, 2);

// Injekcija į SINGLE produkto galeriją (pagrindinė nuotrauka) — kad ir atsidarius produktą būtų tas pats ženkliukas
add_filter('woocommerce_single_product_image_thumbnail_html', function($html, $attachment_id){
    if (!function_exists('is_product') || !is_product()) return $html;
    global $product;
    if (!$product) return $html;
    $pid = $product->get_id();
    if (!get_post_meta($pid, '_dp_pack_qty', true)) return $html;
    static $done = array();
    if (!empty($done[$pid])) return $html; // tik pirma (featured) nuotrauka
    $done[$pid] = true;
    $badge = petshop_dp_badge_html($pid);
    if (!$badge) return $html;
    $pos = strrpos($html, '</div>');
    if ($pos !== false) return substr($html, 0, $pos) . $badge . substr($html, $pos);
    return $html . $badge;
}, 20, 2);

